export function adaptBubblerMap(rel, code) {
  const entries = connections[rel];
  if (!entries) return code;
  for (let i = 0; i < entries.length; i++) {
    const [before, after] = entries[i];
    const at = code.indexOf(before);
    if (at < 0 || code.indexOf(before, at + before.length) !== -1) {
      throw new Error(`INKWAVE patch conflict (Bubbler map ${rel}:${i}): expected one connection`);
    }
    code = code.slice(0, at) + after + code.slice(at + before.length);
  }
  return code;
}
